    local e = FAKES[key]
    if HOLD.key == key and HOLD.tool and HOLD.tool.Parent then return true end
    local ok, why = holdFake(key)
    if ok then notify(L["Holding "] .. e.name) else notify(L["Can't hold "] .. (e and e.name or "unit") .. ": " .. tostring(why)) end
    return ok
end

local function placeFake(key, idx)
    if not FAKES[key] then return false, "unit gone" end
    local cur = slotOfKey(key)
    if cur then return true, cur end
    local why
    if not idx then idx, why = freeSlot() end
    if not idx then return false, why end
    if HOLD.key == key then dropHeld() end
    SLOTS[idx] = { key = key, balance = 0 }
    writeSlot(idx)
    local ok, err = renderSlot(idx)
    if not ok then
        SLOTS[idx] = nil
        writeSlot(idx)
        return false, err
    end
    return true, idx
end
local function pickFromSlot(idx)
    local s = SLOTS[idx]
    if not s then return nil end
    SLOTS[idx] = nil
    writeSlot(idx)
    unrenderSlot(idx)
    return s.key
end
local function removeFake(key)
    local idx = slotOfKey(key)
    if idx then pickFromSlot(idx) end
    if HOLD.key == key then dropHeld() end
    FAKES[key] = nil
    dset(function(r) r.Inventory[key](nil) end)
end
local function setFakeAttr(key, attr, value)
    local e = FAKES[key]
    if not e then return end
    e.attributes[attr] = value
    dset(function(r) r.Inventory[key].attributes[attr](value) end)
    local idx = slotOfKey(key)
    if idx then refreshInfo(SLOT_MODELS[idx], e) writeSlot(idx) end
    if HOLD.key == key and HOLD.tool then refreshInfo(HOLD.tool, e) end
end
local function copyAttrs(a) local o = {} for k, v in pairs(a) do o[k] = v end return o end
local function fakeCount() local n = 0 for _ in pairs(FAKES) do n = n + 1 end return n end
local function placedCount() local n = 0 for _ in pairs(SLOTS) do n = n + 1 end return n end
local function fireClientEvent(re, ...)
    if not re then return end
    local args = table.pack(...)
    if firesignal and pcall(firesignal, re.OnClientEvent, table.unpack(args, 1, args.n)) then return end
    if getconnections then
        pcall(function()
            for _, c in ipairs(getconnections(re.OnClientEvent)) do
                if c.Function then task.spawn(c.Function, table.unpack(args, 1, args.n)) end
            end
        end)
    end
end
local function collectSlot(idx)
    local s = SLOTS[idx]
    if not s or s.balance < 1 then return 0 end
    local amt = math.floor(s.balance)
    s.balance = 0
    addMoney(amt)
    writeSlot(idx)
    pcall(function() local lbl = padLabel(myPlot(), idx) if lbl then lbl.Text = "$0" end end)
    return amt
end


G.nh, G.nw, G.np, G.nh3, G.nw3, G.np3 = nil, nil, nil, nil, nil, nil
