local function hookAlive()
    local probe = Instance.new("RemoteFunction")
    G.probe4 = probe
    local ok, v = pcall(function() return probe:InvokeServer("cwprobe") end)
    G.probe4 = nil
    return ok and v == "cwprobe4-ok"
end
local function installHook()
    if G.hookV == 4 and hookAlive() then return true end
    local hookmm = hookmetamethod or (getgenv and getgenv().hookmetamethod)
    local ncm = getnamecallmethod or (getgenv and getgenv().getnamecallmethod)
    if not (hookmm and ncm) then return false end
    local cc = checkcaller or function() return false end
    local ncc = newcclosure or function(f) return f end
    local old
    local ok = pcall(function()
        old = hookmm(game, "__namecall", ncc(function(self, ...)
            local st = _G.__CW_ADSPAWN
            local route = st and st.route
            if route then
                if st.probe4 and self == st.probe4 then return "cwprobe4-ok" end
                local h = route[self]
                if h then
                    local res = table.pack(pcall(h, ncm(), cc(), ...))
                    if res[1] then
                        if res[2] == true then return table.unpack(res, 3, res.n) end
                        if res[2] == "forward" then return old(self, table.unpack(res, 3, res.n)) end
                    end
                end
            end
            return old(self, ...)
        end))
    end)
    if not ok then return false end
    G.hookV = 4
    return hookAlive()
end

