function FX.fuse(k1, k2, k3)
    local keys = { k1, k2, k3 }
    if not (isFake(k1) and isFake(k2) and isFake(k3)) then return FX.fuseFail("Use 3 spawned units, or 3 real units.") end
    if k1 == k2 or k1 == k3 or k2 == k3 then return FX.fuseFail("Select three different units.") end
    local sum = 0
    for _, k in ipairs(keys) do
        local ok, c = gcall(FX.fu and FX.fu.GetChance, FAKES[k])
        if not (ok and type(c) == "number") or slotOfKey(k) then return FX.fuseFail("A selected unit is missing, locked, or cannot be fused.") end
        sum = sum + c
    end
    local okc, cost = gcall(FX.fc and FX.fc.GetCost, sum)
    cost = (okc and type(cost) == "number") and cost or 0
    if kshown("root:Money") < cost then return FX.fuseFail("You don't have enough money to fuse these units.") end
    local okp, pools = gcall(FX.fu and FX.fu.BuildPools, sum)
    if not (okp and pools) then return FX.fuseFail("No balanced fusion is available for these units. Try different units.") end
    local okr, res = gcall(FX.fu and FX.fu.Roll, pools, Random.new())
    if not (okr and type(res) == "table" and unitEntries[res.name]) then return FX.fuseFail("Fusion failed. Try again.") end
    addMoney(-cost)
    for _, k in ipairs(keys) do removeFake(k) end
    local attrs = { level = 1, mutation = res.mutation, locked = false }
    local key = addFake(res.name, attrs)
    S.spawned = S.spawned + 1
    fireClientEvent(FX.result, { amount = 1, name = res.name, attributes = attrs }, nil, key)
end
local function remoteHandler(self, caller, ...)
    local args = table.pack(...)
    if self == R.roll then
        if caller then return false end
        local name, attrs, spinName
        local luck = M.buff("Luck")
        pcall(function()
            local d0 = data()
            local ok0, dc = gcall(M.Dice and M.Dice.Get, d0 and d0.Dice)
            if ok0 and type(dc) == "table" and type(dc.luck) == "number" then luck = luck * dc.luck end
        end)
        local spin
        for _, nm in ipairs(SPIN_ORDER) do
            if (KEEP["ActiveEntries:" .. nm] or 0) > 0 then spin = nm break end
        end
        if S.rig then
            name, attrs = currentPick()
            if not (unitEntries[name] and BASE_CHANCE[name]) then
                S.rig = false
                queueMsg(tostring(name) .. L[" can't come from rolls. Pick another unit."], "error")
                return false
            end
            if S.rigOnce then S.rig = false end
            if spin then kadd("ActiveEntries:" .. spin, -1) spinName = spin luck = luck * SPINS[spin] end
        elseif spin then
            luck = luck * SPINS[spin]
            local n, m = luckyPick(luck)
            if not n then return false end
            kadd("ActiveEntries:" .. spin, -1)
            spinName = spin
            name, attrs = n, { level = 1, mutation = m, locked = false }
        else
            return false
        end
        local dur = FX.buff("Roll Duration")
        if dur <= 0 then dur = 2.5 end
        task.delay(dur + dur / 3, function()
            if RUNNING then addFake(name, attrs) S.spawned = S.spawned + 1 end
        end)
        kadd("root:Rolls", 1)
        return true, { { result = name, mutation = attrs.mutation } }, luck, 1, spinName ~= nil, spinName
    elseif self == R.spinUse then
        if caller then return false end
        local d = data()
        local e = d and type(d.Inventory) == "table" and d.Inventory[args[1]]
        local nm = type(e) == "table" and e.name or args[1]
        if not SPINS[nm] or (KEEP["Inventory:" .. nm] or 0) <= 0 then return false end
        kadd("Inventory:" .. nm, -1)
        kadd("ActiveEntries:" .. nm, 1)
        queueMsg("+1 " .. nm .. " Consumed! Roll to use it!")
        return true
    elseif self == R.buyDice then
        if caller or type(args[1]) ~= "string" then return false end
        if FX.realCanAfford(FX.dicePrice(args[1]) or 0) then G.diceEq = nil return false end
        job(FX.buyDice, args[1])
        return true
    elseif self == R.equipDice then
        if caller or type(args[1]) ~= "string" then return false end
        if G.ownDice[args[1]] then
            local nm = args[1]
            if G.realDice == nil then local d0 = data() G.realDice = d0 and d0.Dice end
            G.diceEq = nm
            job(function() dset(function(r) r.Dice(nm) end) end)
            return true
        end
        G.diceEq = nil
        return false
    elseif self == R.buyUpgrade then
        if caller or type(args[1]) ~= "string" then return false end
        local u = type(FX.upgrades) == "table" and FX.upgrades[args[1]]
        if not u or FX.realCanAfford(u.price) then return false end
        job(FX.buyUpgrade, args[1])
        return true
    elseif self == R.rebirth then
        if caller then return false end
        local rb = M.Rebirths
        local okn, nextReal = gcall(rb and rb.GetNext, num(data() and data().Rebirth))
        if (KEEP["root:Rebirth"] or 0) == 0 and okn and type(nextReal) == "table" and kreal("root:Money") >= num(nextReal.cost) then return false end
        job(FX.rebirth)
        return true
    elseif self == R.interact then
        if caller then return false end
        local idx = tonumber(args[1])
        if not idx then return false end
        if HOLD.key then
            if realSlotUnit(idx) then job(dropHeld) return false end
            return true
        end
        if SLOTS[idx] then
            local hs = heldState()
            if hs and not isFake(hs) then return false end
            return true
        end
        return false
    elseif self == R.levelUp then
        if caller then return false end
        local idx = tonumber(args[1])
        if not (idx and SLOTS[idx]) then return false end
        return true
    elseif self == R.collect then
        local idx = tonumber(args[1])
        if not (idx and SLOTS[idx]) then return false end
        collectSlot(idx)
        return true
    elseif self == R.equip then
        if isFake(args[1]) then
            if caller then return true, false end
            job(holdAndTell, args[1])
            return true, true
        end
        if HOLD.key then job(dropHeld) end
        return false
    elseif self == R.unequip then
        if HOLD.key then
            if caller then return false end
            job(dropHeld)
            return true, true
        end
        return false
    elseif self == R.sellHeld then
        local key = HOLD.key
        if not key or caller then return false end
        local e = FAKES[key]
        if not e then return false end
        if e.attributes.locked then return true, 0, 0 end
        local price = sellPrice(e)
        removeFake(key)
        addMoney(price)
        return true, price, 1
    elseif self == R.sellInv then
        local keys = type(args[1]) == "table" and args[1] or {}
        local real, gained, n = {}, 0, 0
        for _, k in ipairs(keys) do
            if isFake(k) then
                local e = FAKES[k]
                if not e.attributes.locked and not slotOfKey(k) then gained = gained + sellPrice(e) n = n + 1 removeFake(k) end
            else
                real[#real + 1] = k
            end
        end
        if n == 0 then return false end
        if gained > 0 then addMoney(gained) end
        if #real == 0 then return true, gained, n end
        return "forward", real
    elseif self == R.lock then
        local map = type(args[1]) == "table" and args[1] or {}
        local real, any, touched = {}, false, false
        for k, v in pairs(map) do
            if isFake(k) then setFakeAttr(k, "locked", v == true) touched = true else real[k] = v any = true end
        end
        if not touched then return false end
        if not any then return true end
        return "forward", real
    elseif self == R.towerTeam or self == R.offer then
        for i = 1, args.n do
            local a = args[i]
            local hit = isFake(a)
            if not hit and type(a) == "table" then for _, v in pairs(a) do if isFake(v) then hit = true break end end end
            if hit then
                if not caller then queueMsg("Spawned units can't do that", "error") end
                return true, false
            end
        end
        return false
    elseif self == R.fuse then
        if not (isFake(args[1]) or isFake(args[2]) or isFake(args[3])) then return false end
        if not caller then job(FX.fuse, args[1], args[2], args[3]) end
        return true
    elseif self == R.grade then
        if not isFake(args[1]) then return false end
        if not caller then job(FX.reroll, args[1], "grade", args[2] == true) end
        return true
    elseif self == R.trait then
        if not isFake(args[1]) then return false end
        if not caller then job(FX.reroll, args[1], "trait", args[2] == true) end
        return true
    end
    return false
end

local function slotInteract(idx)
    local s = SLOTS[idx]
    if HOLD.key then
        if realSlotUnit(idx) then dropHeld() return end
        if s then swapIntoSlot(idx, HOLD.key) else placeFake(HOLD.key, idx) end
    elseif s then
        local hs = heldState()
        if hs and not isFake(hs) then pickFromSlot(idx) return end
        local k = pickFromSlot(idx)
        if k then holdAndTell(k) end
    end
end
