local function padCollect()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local plot = myPlot()
    for idx in pairs(SLOTS) do
        local sm = slotModel(plot, idx)
        local hit = sm and find(sm, "Balance.Hitbox")
        if hit and hit:IsA("BasePart") then
            local rel = hit.CFrame:PointToObjectSpace(hrp.Position)
            local half = hit.Size / 2
            if math.abs(rel.X) <= half.X + 1 and math.abs(rel.Z) <= half.Z + 1 and math.abs(rel.Y) <= half.Y + 6 then collectSlot(idx) end
        end
    end
end

local SHOP = { balance = 100000, enabled = true, instant = false, spend = true, items = {}, byId = {}, labels = {}, closeUntil = 0 }
do
    local MC = type(M.Monetization) == "table" and M.Monetization or {}
    local list = {}
    for name, v in pairs(type(MC.Gamepasses) == "table" and MC.Gamepasses or {}) do
        list[#list + 1] = { kind = "pass", name = name, id = num(v.id), price = num(v.price), label = name, order = 1, sort = num(v.price) }
    end
    for _, v in pairs(type(MC.Products) == "table" and MC.Products or {}) do
        local amt = math.max(1, num(v.amount))
        list[#list + 1] = { kind = "spin", name = tostring(v.entry or "Jackpot Spin"), amount = amt, id = num(v.id), price = num(v.price), label = amt .. " Jackpot Spin" .. (amt > 1 and "s" or ""), order = 2, sort = amt }
    end
    for name, v in pairs(type(MC.LimitedUnits) == "table" and MC.LimitedUnits or {}) do
        list[#list + 1] = { kind = "limited", name = name, id = num(v.id), price = num(v.price), label = name .. " (Limited)", order = 3, sort = num(v.price) }
    end
    table.sort(list, function(a, b) if a.order ~= b.order then return a.order < b.order end return a.sort < b.sort end)
    for _, it in ipairs(list) do
        SHOP.items[it.label] = it
        SHOP.labels[#SHOP.labels + 1] = it.label
        if it.id > 0 then SHOP.byId[it.id] = it end
    end
end
