local function fireFinishedLocal(item)
    local isPass = item.kind == "pass" or item.pass
    local sig = isPass and G.mps.PromptGamePassPurchaseFinished or G.mps.PromptProductPurchaseFinished
    local args = isPass and { lp, item.id, true } or { lp.UserId, item.id, true }
    if getconnections then
        pcall(function()
