local function shopBuy(item)
    if not item then return false end
    if item.kind == "pass" and passOwned(item.name) then notify(item.name .. L[" already owned"]) return false end
    if SHOP.spend then
        if SHOP.balance < item.price then notify(L["Not enough Robux"]) return false end
        SHOP.balance = SHOP.balance - item.price
        shopPersist()
    end
    if item.kind == "pass" then
        grantPass(item.name)
        gameNotify(item.name .. " purchased!")
    elseif item.kind == "spin" then
        kadd(SPIN, item.amount)
        if type(M.Spin) == "table" then gcall(M.Spin.PlayShower, item.name) end
        gameNotify("+" .. item.amount .. " Jackpot Spin" .. (item.amount > 1 and "s" or ""))
    elseif item.kind == "limited" then
        if unitEntries[item.name] then addFake(item.name, { level = 1, locked = false }) S.spawned = S.spawned + 1 end
        gameNotify(item.name .. " added to your backpack!")
    end
    fireFinishedLocal(item)
    if item.kind == "other" then notify(L["Bought for R$ "] .. comma(item.price)) end
    return true
end
