local PERKS = { re = remote("BuffService", "RP", "Cache"), safe = { Luck = true, ["Money Multiplier"] = true } }
PERKS.names = { "Luck", "Money Multiplier", "Damage Multiplier", "Sell Multiplier", "Unit Storage", "Health Multiplier", "Roll Duration", "Rolls", "Walkspeed", "Trait Luck", "Grade Luck" }
function PERKS.real()
    if type(G.realBuff) == "table" then return G.realBuff end
    local bc = safeRequire(find(F, "Buffs.BuffController"))
    local out = {}
    if type(bc) == "table" then
        for _, n in ipairs(PERKS.names) do
            local ok, v = gcall(bc.GetBuff, n)
            if ok and type(v) == "number" then out[n] = v end
        end
    end
    G.realBuff = out
    return out
end
function PERKS.push()
    if not (PERKS.re and getconnections) then return end
    local mod = {}
    for k, v in pairs(PERKS.real()) do mod[k] = v end
    local gps = type(M.Monetization) == "table" and M.Monetization.Gamepasses or {}
    for name in pairs(G.passes) do
        local gp = gps[name]
        for buff, b in pairs(type(gp) == "table" and type(gp.buffs) == "table" and gp.buffs or {}) do
            if PERKS.safe[buff] and type(mod[buff]) == "number" then
                if b.bucket == "multiplier" then mod[buff] = mod[buff] * num(b.amount)
                elseif b.bucket == "base" then mod[buff] = mod[buff] + num(b.amount) end
            end
        end
    end
    if (KEEP["root:Rebirth"] or 0) ~= 0 and M.Rebirths then
        local okA, fakeR = gcall(M.Rebirths.Get, math.floor(kshown("root:Rebirth")))
        local okB, realR = gcall(M.Rebirths.Get, math.floor(kreal("root:Rebirth")))
        if okA and okB and type(fakeR) == "table" and type(realR) == "table" then
            if type(mod.Luck) == "number" then mod.Luck = mod.Luck * num(fakeR.luckMultiplier) / math.max(num(realR.luckMultiplier), 0.001) end
            if type(mod["Money Multiplier"]) == "number" then mod["Money Multiplier"] = mod["Money Multiplier"] * num(fakeR.moneyMultiplier) / math.max(num(realR.moneyMultiplier), 0.001) end
        end
    end
    pcall(function()
        for _, c in ipairs(getconnections(PERKS.re.OnClientEvent)) do
            if c.Function and c.Function ~= PERKS.listener then task.spawn(c.Function, mod) end
        end
    end)
end
PERKS.listener = function(v)
    if type(v) ~= "table" then return end
    G.realBuff = v
    if next(G.passes) or (KEEP["root:Rebirth"] or 0) ~= 0 then task.defer(PERKS.push) end
end
if PERKS.re then track(PERKS.re.OnClientEvent:Connect(PERKS.listener)) end
