function REB.slotTemplate(plot)
    local best
    for _, p in ipairs(REB.otherPlots(nil)) do
        local pool = {}
        local slots = p:FindFirstChild("Slots")
        local hid = PC_SCRIPT and PC_SCRIPT:FindFirstChild(p.Name)
        for _, s in ipairs(slots and slots:GetChildren() or {}) do pool[#pool + 1] = s end
        for _, s in ipairs(hid and hid:GetChildren() or {}) do pool[#pool + 1] = s end
        for _, s in ipairs(pool) do
            if s:IsA("Model") and s:FindFirstChild("Base") and s:FindFirstChild("Balance") and s:FindFirstChild("Upgrade") and not s:GetAttribute("CWFake") then
                best = s
                break
            end
        end
        if best then break end
    end
    if not best then return nil end
    local c = best:Clone()
    for _, ch in ipairs(c:GetChildren()) do
        if ch:IsA("Model") and ch:FindFirstChildOfClass("Humanoid") then ch:Destroy() end
    end
    for _, d in ipairs(c:GetDescendants()) do
