function REB.sync()
    local plot = myPlot()
    local d = data()
    if not (plot and d) then return end
    local rb = num(d.Rebirth)
    REB.missing = nil
    for _, fl in ipairs(REB.floors()) do
        if fl.model then
            local have = plot:FindFirstChild(fl.model)
            if num(fl.rebirth) <= rb then
                if not have and not REB.cloneFloor(plot, fl.model) then REB.missing = fl.model end
            elseif have and have:GetAttribute("CWFake") then
                have:Destroy()
            end
        end
    end
    local slots = plot:FindFirstChild("Slots")
    local poss = plot:FindFirstChild("SlotPositions")
    if not slots then return end
    for _, fl in ipairs(REB.floors()) do
        local floorOk = not fl.model or plot:FindFirstChild(fl.model) ~= nil
        for i = num(fl.firstSlot), num(fl.lastSlot) do
            local sm = slotModel(plot, i)
            local unlocked = slotUnlocked(i)
            if floorOk and not sm and unlocked then
                local pos = poss and poss:FindFirstChild(tostring(i))
                local c = pos and REB.slotTemplate(plot)
                if c then
                    c.Name = tostring(i)
                    c:PivotTo(pos.CFrame)
                    c.Parent = slots
                    sm = c
                end
            elseif sm and sm:GetAttribute("CWFake") and (not floorOk or not unlocked) then
                if SLOTS[i] then pickFromSlot(i) end
                sm:Destroy()
                sm = nil
