local STREAM = { on = false, name = "", orig = setmetatable({}, { __mode = "k" }), conns = setmetatable({}, { __mode = "k" }), roles = safeRequire(find(F, "Staff.StaffRoles")) }
function STREAM.fake() return (STREAM.name ~= "" and STREAM.name) or "Player" end
function STREAM.real() return { lp.DisplayName, lp.Name } end
local function plainEsc(s) return (s:gsub("[%%%(%)%.%+%-%*%?%[%]%^%$]", "%%%0")) end
function STREAM.swap(s)
    if type(s) ~= "string" or s == "" then return s end
    local fake = STREAM.fake():gsub("%%", "%%%%")
    local names = STREAM.real()
    table.sort(names, function(a, b) return #a > #b end)
    for _, n in ipairs(names) do
        if n ~= "" and n ~= STREAM.fake() then s = s:gsub(plainEsc(n), fake) end
    end
    return s
end
function STREAM.hasName(s)
    if type(s) ~= "string" then return false end
    for _, n in ipairs(STREAM.real()) do if n ~= "" and s:find(n, 1, true) then return true end end
    return false
end
local hui
pcall(function() hui = gethui and gethui() end)
function STREAM.fix(lbl)
    if not STREAM.on then return end
    if hui and lbl:IsDescendantOf(hui) then return end
    local t = lbl.Text
    if STREAM.hasName(t) then
        STREAM.orig[lbl] = t
        local n = STREAM.swap(t)
        if n ~= t then pcall(function() lbl.Text = n end) end
    end
end
function STREAM.watch(lbl)
    if STREAM.conns[lbl] or not (lbl:IsA("TextLabel") or lbl:IsA("TextButton")) then return end
    STREAM.conns[lbl] = lbl:GetPropertyChangedSignal("Text"):Connect(function() STREAM.fix(lbl) end)
    STREAM.fix(lbl)
end
function STREAM.scan(root)
    if not root then return end
    local ok, ds = pcall(function() return root:GetDescendants() end)
    if not ok then return end
    for _, d in ipairs(ds) do
        if (d:IsA("TextLabel") or d:IsA("TextButton")) and STREAM.hasName(d.Text) then STREAM.watch(d) end
    end
end
function STREAM.roots() return { CoreGui, lp:FindFirstChildOfClass("PlayerGui"), workspace } end
for _, root in ipairs(STREAM.roots()) do
    if root then
        pcall(function()
            track(root.DescendantAdded:Connect(function(d)
                if STREAM.on and (d:IsA("TextLabel") or d:IsA("TextButton")) then
                    task.defer(function() if d.Parent and STREAM.hasName(d.Text) then STREAM.watch(d) end end)
                end
            end))
        end)
    end
end
function STREAM.chat(msg)
    local src = msg.TextSource
    local props
    local pre = {}
    if src then
        local ok, role, info = pcall(function() return STREAM.roles.GetRole(src.UserId) end)
        if ok and info and info.color then table.insert(pre, ('<font color="#%s">[%s]</font>'):format(info.color:ToHex(), tostring(role))) end
        local plr = Players:GetPlayerByUserId(src.UserId)
        if plr and plr:GetAttribute("VIP") then table.insert(pre, '<font color="#FFD54A">[VIP]</font>') end
    end
    local prefix = msg.PrefixText
    local text = msg.Text
    if STREAM.on then
        prefix = STREAM.swap(prefix)
        text = STREAM.swap(text)
    end
    if #pre > 0 or prefix ~= msg.PrefixText or text ~= msg.Text then
        props = Instance.new("TextChatMessageProperties")
        props.PrefixText = (#pre > 0 and (table.concat(pre, " ") .. " ") or "") .. prefix
        if text ~= msg.Text then props.Text = text end
    end
    return props
end
function STREAM.apply(on)
    STREAM.on = on
    local tcs = game:GetService("TextChatService")
    if on then
        pcall(function() tcs.OnIncomingMessage = STREAM.chat end)
        for _, root in ipairs(STREAM.roots()) do STREAM.scan(root) end
    else
        for lbl, t in pairs(STREAM.orig) do
            pcall(function() if lbl.Parent then lbl.Text = STREAM.swap(t) == lbl.Text and t or lbl.Text end end)
        end
        STREAM.orig = setmetatable({}, { __mode = "k" })
        for lbl, c in pairs(STREAM.conns) do pcall(function() c:Disconnect() end) end
        STREAM.conns = setmetatable({}, { __mode = "k" })
    end
    pcall(function()
        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if hum then hum.DisplayName = on and STREAM.fake() or lp.DisplayName end
    end)
end
track(lp.CharacterAdded:Connect(function(c)
    if not STREAM.on then return end
    local hum = c:WaitForChild("Humanoid", 10)
    if hum then hum.DisplayName = STREAM.fake() end
end))
onClean(function() if STREAM.on then STREAM.apply(false) end end)
