                realInvoke("UnitService", "Unequip")
                task.wait(0.5)
                for _, idx in ipairs(list) do
                    if not RUNNING then break end
                    realFire("PlotService", "CollectBalance", idx)
                    task.wait(0.2)
                    realFire("PlotService", "InteractSlot", idx)
                    local t0 = os.clock()
                    while realSlotUnit(idx) and os.clock() - t0 < 2.5 do task.wait(0.1) end
                    task.wait(0.55)
                    realInvoke("UnitService", "Unequip")
                    if not realSlotUnit(idx) then n = n + 1 end
                    task.wait(0.55)
                end
            end)
            S.unequipping = false
            notify(n > 0 and (L["Unequipped "] .. n .. L[" real units"]) or L["Couldn't unequip, try again"])
        end)
    end })
    Pl:AddButton({ Text = L["Put Real Units Back"], Func = function()
        realFire("PlotService", "EquipBest")
        notify(L["Placing your best real units"])
    end })

    local Mg = Tabs.Spawner:AddRightGroupbox(L["Manage"], "menu")
    Mg:AddButton({ Text = L["Unlock Whole Index"], Func = function()
        for name in pairs(unitEntries) do
            dset(function(r)
                if not r.DiscoveredUnits[name]() then r.DiscoveredUnits[name]({ mutations = {} }) end
                for _, mut in ipairs(MUT_LIST) do r.DiscoveredUnits[name].mutations[mut](true) end
            end)
        end
        notify(L["Index unlocked"])
    end })
    Mg:AddButton({ Text = L["Sell Spawned Units"], Tooltip = L["Keeps locked and placed units."], Func = function()
        local total, n, kept = 0, 0, 0
        local list = {}
        for key, e in pairs(FAKES) do
            if not e.attributes.locked and not slotOfKey(key) then list[#list + 1] = key total = total + sellPrice(e) else kept = kept + 1 end
        end
        for _, key in ipairs(list) do removeFake(key) n = n + 1 end
        if total > 0 then addMoney(total) end
        local keptTxt = kept > 0 and (" (" .. kept .. " placed/locked kept)") or ""
        notify(n > 0 and (L["Sold "] .. n .. L[" for $"] .. fmt(total) .. keptTxt) or (L["Nothing to sell"] .. keptTxt))
    end })
    Mg:AddButton({ Text = L["Delete Spawned Units"], Func = function()
        local list = {}
        for key in pairs(FAKES) do list[#list + 1] = key end
        for _, key in ipairs(list) do removeFake(key) end
        notify(#list > 0 and (L["Deleted "] .. #list .. L[" units"]) or L["Nothing to delete"])
    end })
    statusLabels.session = Mg:AddLabel("-", true)
end)

section(L["Shop"], function()
    local Rb = Tabs.Shop:AddLeftGroupbox(L["Robux"], "dollar-sign")
    Rb:AddInput("sh_bal", { Default = "", Numeric = false, Finished = true, ClearTextOnFocus = false, Text = L["Robux Balance"], Placeholder = L["e.g. 100K"] })
    Rb:AddButton({ Text = L["Set Balance"], Func = function()
        local v = parseNum(Opt.sh_bal.Value)
        if not v or v < 0 then notify(L["Type a number like 100K"]) return end
        SHOP.balance = math.floor(v)
        shopPersist()
        notify(L["Robux set to "] .. comma(SHOP.balance))
    end })
    Rb:AddToggle("sh_on", { Text = L["Robux Spoofer"], Default = true, Tooltip = L["Game purchases use this balance."], Callback = function(v) SHOP.enabled = v end })
    Rb:AddToggle("sh_instant", { Text = L["Skip Robux Prompt"], Default = false, Callback = function(v) SHOP.instant = v end })
    Rb:AddToggle("sh_spend", { Text = L["Spend Robux On Buy"], Default = true, Callback = function(v) SHOP.spend = v end })
    statusLabels.robux = Rb:AddLabel("-", true)

    local Qb = Tabs.Shop:AddLeftGroupbox(L["Quick Buy"], "zap")
    Qb:AddDropdown("sh_item", { Values = SHOP.labels, Default = SHOP.labels[1], Text = L["Item"] })
    Qb:AddButton({ Text = "Buy", Func = function()
        local it = SHOP.items[Opt.sh_item.Value]
        if not it then notify(L["Pick an item"]) return end
        if it.kind == "pass" and passOwned(it.name) then notify(it.name .. L[" already owned"]) return end
        if SHOP.instant or not canArm or not S.hookOk then shopBuy(it) return end
        SHOP.pending, SHOP.pendingAt = { id = it.id, pass = it.kind == "pass", item = it }, os.clock()
        local ok = pcall(function()
            if it.kind == "pass" then G.mps:PromptGamePassPurchase(lp, it.id) else G.mps:PromptProductPurchase(lp, it.id) end
        end)
        if not ok then SHOP.pending = nil shopBuy(it) end
    end })
    Qb:AddButton({ Text = L["Buy All Gamepasses"], Func = function()
        local n = 0
        for _, label in ipairs(SHOP.labels) do
            local it = SHOP.items[label]
            if it.kind == "pass" and not passOwned(it.name) then
                if SHOP.spend and SHOP.balance < it.price then break end
                if shopBuy(it) then n = n + 1 end
            end
        end
        if n == 0 then notify(L["Nothing bought"]) end
    end })
    Qb:AddButton({ Text = L["Remove Fake Gamepasses"], Func = function()
        local n = 0
        for name in pairs(G.passes) do
            G.passes[name] = nil
            dset(function(r) r.OwnedGamepasses[name](nil) end)
            n = n + 1
        end
        S.perkDirty = true
        notify(n > 0 and (L["Removed "] .. n) or L["No fake gamepasses"])
    end })
    statusLabels.item = Qb:AddLabel("-", true)

    local Ec = Tabs.Shop:AddRightGroupbox(L["Economy"], "trending-up")
    local St = Tabs.Shop:AddRightGroupbox(L["Stats & Spins"], "dumbbell")
    local function field(box, id, text, ph)
        box:AddInput(id, { Default = "", Numeric = false, Finished = true, ClearTextOnFocus = false, Text = text, Placeholder = ph or L["e.g. 10M"] })
    end
    local function readField(id)
        local raw = Opt[id] and Opt[id].Value
        if raw == nil or tostring(raw):gsub("%s", "") == "" then return nil, false end
        local v = parseNum(raw)
        return v, v == nil
    end
    local function setMany(map, okMsg)
        local any, bad = false, false
        for id, key in pairs(map) do
            local v, b = readField(id)
            if v and v >= 0 then kset(key, math.floor(v)) any = true elseif b or (v and v < 0) then bad = true end
        end
        notify(any and okMsg or (bad and L["Type numbers like 500 or 10K"] or L["Type an amount first"]))
    end
    field(Ec, "sp_money", L["Cash"])
    Ec:AddButton({ Text = L["Set Cash"], Func = function()
        local v, bad = readField("sp_money")
        if not v or v < 0 then notify(bad and L["Type a number like 10M"] or L["Type an amount first"]) return end
        kset("root:Money", v)
        notify(L["Cash set to $"] .. fmt(v))
    end })
    Ec:AddDivider()
    field(Ec, "sp_gems", L["Gems"], L["e.g. 500"])
    field(Ec, "sp_rerolls", L["Trait Rerolls"], L["e.g. 500"])
    field(Ec, "sp_tickets", L["Tickets"], L["e.g. 500"])
    Ec:AddButton({ Text = L["Set Items"], Func = function()
        setMany({ sp_gems = "Inventory:Gems", sp_rerolls = "Inventory:Trait Reroll", sp_tickets = "Inventory:Tickets" }, "Items updated")
    end })

    field(St, "sp_spins", L["Jackpot Spins"], L["e.g. 10"])
    field(St, "sp_lspins", L["Lucky Spins"], L["e.g. 10"])
    St:AddButton({ Text = L["Set Spins"], Func = function()
        setMany({ sp_spins = "Inventory:Jackpot Spin", sp_lspins = "Inventory:Lucky Spin" }, "Spins updated")
    end })
    St:AddDivider()
    field(St, "sp_rolls", L["Total Rolls"], L["e.g. 1M"])
    St:AddButton({ Text = L["Set Rolls"], Func = function()
        local v, bad = readField("sp_rolls")
        if not v or v < 0 then notify(bad and L["Type a number like 1M"] or L["Type an amount first"]) return end
        kset("root:Rolls", math.floor(v))
        pcall(function() lp.leaderstats.Rolls.Value = math.floor(v) end)
        notify(L["Rolls set to "] .. fmt(math.floor(v)))
    end })
    field(St, "sp_rebirths", L["Rebirths"], "0 - " .. FX.maxRebirth())
    St:AddButton({ Text = L["Set Rebirths"], Func = function()
        local v, bad = readField("sp_rebirths")
        if not v or v < 0 then notify(bad and L["Type a number like 5"] or L["Type an amount first"]) return end
        local top = FX.maxRebirth()
        v = math.min(math.floor(v), top)
        kset("root:Rebirth", v)
        S.perkDirty = true
        notify(L["Rebirths set to "] .. v .. (v == top and L[" (max)"] or ""))
    end })
    St:AddDivider()
    St:AddButton({ Text = L["Reset To Real"], Tooltip = L["Puts every stat back."], Func = function()
        for id in pairs(KEEP) do
            local real = kreal(id)
            KEEP[id] = 0
            SHOWN[id] = real
            kwrite(id, real)
        end
        pcall(FX.clearOwned)
        G.ownDice, G.ownUp, G.diceEq = {}, {}, nil
        pcall(function() lp.leaderstats.Money.Value = fmt(money()) end)
        pcall(function() lp.leaderstats.Rolls.Value = num(data().Rolls) end)
        S.perkDirty = true
        notify(L["Back to your real stats"])
    end })
end)

task.spawn(function()
    while RUNNING do
        pcall(function()
            if Toggles.sp_rig and Toggles.sp_rig.Value ~= S.rig then Toggles.sp_rig:SetValue(S.rig) end
        end)
        while #MSGS > 0 do
            local m = table.remove(MSGS, 1)
            gameNotify(m[1], m[2])
        end
        while #S.buyQueue > 0 do
            local p = table.remove(S.buyQueue, 1)
            pcall(function() shopBuy(resolveItem(p)) end)
        end
        pcall(function()
            local name, attrs = currentPick()
            local inc = unitIncome(name, attrs)
            statusLabels.preview:SetText(string.format(L["%s  ·  %s\n$%s/s  ·  sells $%s%s"], tostring(name), unitRarity(name, attrs.mutation), fmt(inc), fmt(inc * 40), BASE_CHANCE[name] and "" or L["\nCan't come from rolls"]))
        end)
        pcall(function()
            local lines = { string.format("Spawned %d  ·  On plot %d", fakeCount(), placedCount()) }
            if not S.hookOk then lines[#lines + 1] = "Executor hook failed, re-run script" end
            if REB.missing then lines[#lines + 1] = REB.missing .. " shows once a player here has it" end
            local held = HOLD.key and FAKES[HOLD.key]
            if held then lines[#lines + 1] = L["Holding "] .. held.name end
            if S.perSec > 0 then lines[#lines + 1] = "Plot earns $" .. fmt(S.perSec) .. L["/s"] end
            if S.rig then lines[#lines + 1] = "Next roll rigged" end
            for _, nm in ipairs(SPIN_ORDER) do
                local c = KEEP["ActiveEntries:" .. nm] or 0
                if c > 0 then lines[#lines + 1] = nm .. " rolls ready: " .. c end
            end
            statusLabels.session:SetText(table.concat(lines, "\n"))
        end)
        pcall(function()
            statusLabels.robux:SetText(S.hookOk and (L["Balance R$ "] .. comma(SHOP.balance)) or L["Spoofer off: prompts are REAL"])
            local it = SHOP.items[Opt.sh_item.Value]
            if it then
                local owned = it.kind == "pass" and passOwned(it.name)
                statusLabels.item:SetText(owned and L["Owned"] or (L["Price R$ "] .. comma(it.price)))
            end
        end)
        task.wait(0.3)
    end
end)
S.hookOk = installHook()
job(rebuildCards)

local function unload()
    pcall(function() if _G.__CW_ADS_CLEAN then _G.__CW_ADS_CLEAN() end end)
    pcall(function() Library:Unload() end)
end
